                            +(PQ[c0]*(PQ[c1]*delta[d0][d1] + PQ[d0]*delta[c1][d1] + PQ[d1]*delta[c1][d0]) + PQ[c1]*(PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0]) + PQ[d0]*PQ[d1]*delta[c0][c1])*(PA_0*(-PA_1*(PA_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PB_0*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0]) + PB_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1])) + PA_x*PB_1*(PA_1*delta[b0][g1] + PB_0*delta[a1][g1] + PB_y*delta[a1][b0] - PQ[a1]*delta[b0][g1] - PQ[b0]*delta[a1][g1] - PQ[g1]*delta[a1][b0]) - PA_x*PB_y*(PQ[a1]*delta[b0][b1] + PQ[b0]*delta[a1][b1] + PQ[b1]*delta[a1][b0]) - PB_0*PB_1*(PQ[a1]*delta[g0][g1] + PQ[g0]*delta[a1][g1] + PQ[g1]*delta[a1][g0]) + PB_0*PB_y*(PA_1*delta[b1][g0] + PA_x*delta[a1][b1] + PB_1*delta[a1][g0] - PQ[a1]*delta[b1][g0] - PQ[b1]*delta[a1][g0] - PQ[g0]*delta[a1][b1])) + PA_1*PB_y*(PA_0*PB_1*delta[b0][g0] + PA_x*(PA_0*delta[b0][b1] + PB_0*delta[a0][b1] + PB_1*delta[a0][b0] - PQ[a0]*delta[b0][b1] - PQ[b0]*delta[a0][b1] - PQ[b1]*delta[a0][b0]) - PB_0*(PQ[a0]*delta[b1][g0] + PQ[b1]*delta[a0][g0] + PQ[g0]*delta[a0][b1])) + PA_x*PB_0*(PA_0*PA_1*delta[b1][g1] - PA_0*(PQ[a1]*delta[b1][g1] + PQ[b1]*delta[a1][g1] + PQ[g1]*delta[a1][b1]) - PA_1*(PQ[a0]*delta[b1][g1] + PQ[b1]*delta[a0][g1] + PQ[g1]*delta[a0][b1]) + PB_1*PB_y*delta[a0][a1] - PB_1*(PQ[a0]*delta[a1][g1] + PQ[a1]*delta[a0][g1] + PQ[g1]*delta[a0][a1]) - PB_y*(PQ[a0]*delta[a1][b1] + PQ[a1]*delta[a0][b1] + PQ[b1]*delta[a0][a1])) + PB_1*(-PA_1*PA_x*(PQ[a0]*delta[b0][g1] + PQ[b0]*delta[a0][g1] + PQ[g1]*delta[a0][b0]) + PA_1*PB_0*(PA_0*delta[g0][g1] + PA_x*delta[a0][g1] + PB_y*delta[a0][g0] - PQ[a0]*delta[g0][g1] - PQ[g0]*delta[a0][g1] - PQ[g1]*delta[a0][g0]) - PB_y*(PA_0*(PQ[a1]*delta[b0][g0] + PQ[b0]*delta[a1][g0] + PQ[g0]*delta[a1][b0]) + PA_1*(PQ[a0]*delta[b0][g0] + PQ[b0]*delta[a0][g0] + PQ[g0]*delta[a0][b0]) + PA_x*(PQ[a0]*delta[a1][b0] 