a1]*delta[b0][g0]*delta[b1][g1] + PQ[a0]*PQ[a1]*delta[b0][g1]*delta[b1][g0] + PQ[a0]*PQ[b0]*delta[a1][b1]*delta[g0][g1] + PQ[a0]*PQ[b0]*delta[a1][g0]*delta[b1][g1] + PQ[a0]*PQ[b0]*delta[a1][g1]*delta[b1][g0] + PQ[a0]*PQ[b1]*delta[a1][b0]*delta[g0][g1] + PQ[a0]*PQ[b1]*delta[a1][g0]*delta[b0][g1] + PQ[a0]*PQ[b1]*delta[a1][g1]*delta[b0][g0] + PQ[a0]*PQ[g0]*delta[a1][b0]*delta[b1][g1] + PQ[a0]*PQ[g0]*delta[a1][b1]*delta[b0][g1] + PQ[a0]*PQ[g0]*delta[a1][g1]*delta[b0][b1] + PQ[a0]*PQ[g1]*delta[a1][b0]*delta[b1][g0] + PQ[a0]*PQ[g1]*delta[a1][b1]*delta[b0][g0] + PQ[a0]*PQ[g1]*delta[a1][g0]*delta[b0][b1] + PQ[a1]*PQ[b0]*delta[a0][b1]*delta[g0][g1] + PQ[a1]*PQ[b0]*delta[a0][g0]*delta[b1][g1] + PQ[a1]*PQ[b0]*delta[a0][g1]*delta[b1][g0] + PQ[a1]*PQ[b1]*delta[a0][b0]*delta[g0][g1] + PQ[a1]*PQ[b1]*delta[a0][g0]*delta[b0][g1] + PQ[a1]*PQ[b1]*delta[a0][g1]*delta[b0][g0] + PQ[a1]*PQ[g0]*delta[a0][b0]*delta[b1][g1] + PQ[a1]*PQ[g0]*delta[a0][b1]*delta[b0][g1] + PQ[a1]*PQ[g0]*delta[a0][g1]*delta[b0][b1] + PQ[a1]*PQ[g1]*delta[a0][b0]*delta[b1][g0] + PQ[a1]*PQ[g1]*delta[a0][b1]*delta[b0][g0] + PQ[a1]*PQ[g1]*delta[a0][g0]*delta[b0][b1] + PQ[b0]*PQ[b1]*delta[a0][a1]*delta[g0][g1] + PQ[b0]*PQ[b1]*delta[a0][g0]*delta[a1][g1] + PQ[b0]*PQ[b1]*delta[a0][g1]*delta[a1][g0] + PQ[b0]*PQ[g0]*delta[a0][a1]*delta[b1][g1] + PQ[b0]*PQ[g0]*delta[a0][b1]*delta[a1][g1] + PQ[b0]*PQ[g0]*delta[a0][g1]*delta[a1][b1] + PQ[b0]*PQ[g1]*delta[a0][a1]*delta[b1][g0] + PQ[b0]*PQ[g1]*delta[a0][b1]*delta[a1][g0] + PQ[b0]*PQ[g1]*delta[a0][g0]*delta[a1][b1] + PQ[b1]*PQ[g0]*delta[a0][a1]*delta[b0][g1] + PQ[b1]*PQ[g0]*delta[a0][b0]*delta[a1][g1] + PQ[b1]*PQ[g0]*delta[a0][g1]*delta[a1][b0] + PQ[b1]*PQ[g1]*delta[a0][a1]*delta[b0][g0] + PQ[b1]*PQ[g1]*delta[a0][b0]*delta[a1][g0] + PQ[b1]*PQ[g1]*delta[a0][g0]*delta[a1][b0] + PQ[g0]*PQ[g1]*delta[a0][a1]*delta[b0][b1] + PQ[g0]*PQ[g1]*delta[a0][b0]*delta[a1][b1] + PQ[g0]*PQ[g1]*delta[a0][b1]*delta[a1][b0])

                            +(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0])*(PQ[a0]*PQ[g0]*PQ[g1]*(PA_1*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PB_0*PB_1*PQ[a1]) + PQ[a1]*PQ[b1]*(PA_x*PQ[a0]*(PB_0*PQ[g1] + PB_y*PQ[b0]) + PB_0*PQ[g0]*(PA_0*PQ[g1] + PB_y*PQ[a0])) + PQ[b0]*(PA_0*(PQ[a1]*PQ[g1]*(PA_x*PQ[b1] + PB_1*PQ[g0]) + PQ[b1]*PQ[g0]*(PA_1*PQ[g1] + PB_y*PQ[a1])) + PQ[a0]*(PA_1*PQ[b1] + PB_1*PQ[a1])*(PA_x*PQ[g1] + PB_y*PQ[g0])))

                        )


                    );

            double hess_ij_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + i] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j_prim],
                hess_ij_xy * ik_factor_D * 2.0 * frac_exact_exchange);
