            const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                        + F10_t[5] * (-0.5) * S1 * S1 * S1 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * (

                            +(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0])*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1])*(PQ[c0]*(PQ[c1]*delta[d0][d1] + PQ[d0]*delta[c1][d1] + PQ[d1]*delta[c1][d0]) + PQ[c1]*(PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0]) + PQ[d0]*PQ[d1]*delta[c0][c1])

                            +PQ[c0]*PQ[c1]*((PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0])*(PQ[d0]*(delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + PQ[d1]*(delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0])) + (PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1])*(PQ[d0]*(delta[a0][d1]*delta[a1][g0] + delta[a0][g0]*delta[a1][d1]) + PQ[d1]*(delta[a0][d0]*delta[a1][g0] + delta[a0][g0]*delta[a1][d0]))) + PQ[d0]*PQ[d1]*((PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0])*(PQ[c0]*(delta[b0][c1]*delta[b1][g1] + delta[b0][g1]*delta[b1][c1]) + PQ[c1]*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0])) + (PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1])*(PQ[c0]*(delta[a0][c1]*delta[a1][g0] + delta[a0][g0]*delta[a1][c1]) + PQ[c1]*(delta[a0][c0]*delta[a1][g0] + delta[a0][g0]*delta[a1][c0])))

                            +PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*(delta[a0][g0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1]) + delta[a1][g0]*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1]))

                        )


                    );

            double hess_ij_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + i] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j_prim],
                hess_ij_xy * ik_factor_D * 2.0 * frac_exact_exchange);
        }
    }

    __syncthreads();
}

