                                const uint32_t  pair_inds_count_for_K_dd,
                                const double*   d_prim_info,
                                const uint32_t* d_prim_aoinds,
                                const uint32_t  d_prim_count,
                                const double    dd_max_D,
                                const double*   mat_D_full_AO,
                                const uint32_t  naos,
                                const double*   Q_K_dd,
                                const uint32_t* D_inds_K_dd,
                                const uint32_t* pair_displs_K_dd,
                                const uint32_t* pair_counts_K_dd,
                                const double*   pair_data_K_dd,
                                const uint32_t* prim_cart_ao_to_atom_inds,
                                const uint32_t  natoms,
                                const uint32_t  s_prim_count,
                                const uint32_t  p_prim_count,
                                const double*   boys_func_table,
                                const double*   boys_func_ft,
                                const double    omega,
                                const double    eri_threshold)
{
    // each thread block scans over [i?|k?] and sum up to a primitive K matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ uint32_t i, k, count_i, count_k, displ_i, displ_k;
    __shared__ double   a_i, r_i[3], a_k, r_k[3], ik_factor_D;
    __shared__ uint32_t a0, a1, c0, c1;
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    const uint32_t ik = blockIdx.x;

    // we make sure that ik < pair_inds_count_for_K_dd when calling the kernel

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
        d_cart_inds[3][0] = 1; d_cart_inds[3][1] = 1;
        d_cart_inds[4][0] = 1; d_cart_inds[4][1] = 2;
        d_cart_inds[5][0] = 2; d_cart_inds[5][1] = 2;

        delta[0][0] = 1.0; delta[0][1] = 0.0; delta[0][2] = 0.0;
        delta[1][0] = 0.0; delta[1][1] = 1.0; delta[1][2] = 0.0;
        delta[2][0] = 0.0; delta[2][1] = 0.0; delta[2][2] = 1.0;

        g0 = hess_cart_ind_0;
        g1 = hess_cart_ind_1;

        i = pair_inds_i_for_K_dd[ik];
        k = pair_inds_k_for_K_dd[ik];

        count_i = pair_counts_K_dd[i];
        count_k = pair_counts_K_dd[k];

        displ_i = pair_displs_K_dd[i];
        displ_k = pair_displs_K_dd[k];

        a_i = d_prim_info[i / 6 + d_prim_count * 0];

        r_i[0] = d_prim_info[i / 6 + d_prim_count * 2];
        r_i[1] = d_prim_info[i / 6 + d_prim_count * 3];
        r_i[2] = d_prim_info[i / 6 + d_prim_count * 4];

        a_k = d_prim_info[k / 6 + d_prim_count * 0];

        r_k[0] = d_prim_info[k / 6 + d_prim_count * 2];
        r_k[1] = d_prim_info[k / 6 + d_prim_count * 3];
        r_k[2] = d_prim_info[k / 6 + d_prim_count * 4];

        ik_factor_D = (static_cast<double>(i != k) + 1.0) * D_ik_for_K_dd[ik];

        a0 = d_cart_inds[i % 6][0];
        a1 = d_cart_inds[i % 6][1];
        c0 = d_cart_inds[k % 6][0];
        c1 = d_cart_inds[k % 6][1];
    }

    __syncthreads();

    for (uint32_t m = 0; m < (count_i + TILE_DIM_Y_K - 1) / TILE_DIM_Y_K; m++)
    {
        const uint32_t j = m * TILE_DIM_Y_K + threadIdx.y;

        // sync threads before starting a new scan
        __syncthreads();

        double Q_ij, a_j, r_j[3], S_ij_00, S1, inv_S1;
        double PA_0, PA_1, PB_0, PB_1, PA_x, PB_y;
        uint32_t j_prim, j_cgto, b0, b1;

        if (j < count_i)
        {
            Q_ij   = Q_K_dd[displ_i + j];

            j_prim = D_inds_K_dd[displ_i + j];

            j_cgto = d_prim_aoinds[(j_prim / 6) + d_prim_count * (j_prim % 6)];

            a_j = d_prim_info[j_prim / 6 + d_prim_count * 0];

            r_j[0] = d_prim_info[j_prim / 6 + d_prim_count * 2];
            r_j[1] = d_prim_info[j_prim / 6 + d_prim_count * 3];
            r_j[2] = d_prim_info[j_prim / 6 + d_prim_count * 4];

            S1 = a_i + a_j;
            inv_S1 = 1.0 / S1;

            S_ij_00 = pair_data_K_dd[displ_i + j];

            PA_x = (a_j  * inv_S1) * (r_j[g0] - r_i[g0]);
            PB_y = (-a_i * inv_S1) * (r_j[g1] - r_i[g1]);

            b0 = d_cart_inds[j_prim % 6][0];
            b1 = d_cart_inds[j_prim % 6][1];

            PA_0 = (a_j  * inv_S1) * (r_j[a0] - r_i[a0]);
            PA_1 = (a_j  * inv_S1) * (r_j[a1] - r_i[a1]);
            PB_0 = (-a_i * inv_S1) * (r_j[b0] - r_i[b0]);
            PB_1 = (-a_i * inv_S1) * (r_j[b1] - r_i[b1]);

        }

        for (uint32_t n = 0; n < (count_k + TILE_DIM_X_K - 1) / TILE_DIM_X_K; n++)
        {
            const uint32_t l = n * TILE_DIM_X_K + threadIdx.x;

            // Q_kl == Q_K_dd[displ_k + l]
            if ((j >= count_i) || (l >= count_k) || (fabs(Q_ij * Q_K_dd[displ_k + l] * dd_max_D) <= eri_threshold))
            {
                break;
            }

            // const auto Q_kl = Q_K_dd[displ_k + l];

            const auto l_prim = D_inds_K_dd[displ_k + l];

            const auto l_cgto = d_prim_aoinds[(l_prim / 6) + d_prim_count * (l_prim % 6)];

            const auto a_l = d_prim_info[l_prim / 6 + d_prim_count * 0];

            const double r_l[3] = {d_prim_info[l_prim / 6 + d_prim_count * 2],
                                   d_prim_info[l_prim / 6 + d_prim_count * 3],
                                   d_prim_info[l_prim / 6 + d_prim_count * 4]};

            const auto S_kl_00 = pair_data_K_dd[displ_k + l];

            const auto d0 = d_cart_inds[l_prim % 6][0];
            const auto d1 = d_cart_inds[l_prim % 6][1];

            // J. Chem. Phys. 84, 3963-3974 (1986)

            const auto S2 = a_k + a_l;

            const auto inv_S2 = 1.0 / S2;
            const auto inv_S4 = 1.0 / (S1 + S2);

            const double PQ[3] = {(a_k * r_k[0] + a_l * r_l[0]) * inv_S2 - (a_i * r_i[0] + a_j * r_j[0]) * inv_S1,
                                  (a_k * r_k[1] + a_l * r_l[1]) * inv_S2 - (a_i * r_i[1] + a_j * r_j[1]) * inv_S1,
                                  (a_k * r_k[2] + a_l * r_l[2]) * inv_S2 - (a_i * r_i[2] + a_j * r_j[2]) * inv_S1};

            const auto r2_PQ = PQ[0] * PQ[0] + PQ[1] * PQ[1] + PQ[2] * PQ[2];

            const auto rho = S1 * S2 * inv_S4;

            double d2 = 1.0;

            if (omega != 0.0) d2 = omega * omega / (rho + omega * omega);

            const auto Lambda = sqrt(4.0 * rho * d2 * MATH_CONST_INV_PI);

            double F10_t[7];

            gpu::computeBoysFunction(F10_t, rho * d2 * r2_PQ, 6, boys_func_table, boys_func_ft);

            if (omega != 0.0)
            {
                F10_t[1] *= d2;
                F10_t[2] *= d2 * d2;
                F10_t[3] *= d2 * d2 * d2;
                F10_t[4] *= d2 * d2 * d2 * d2;
                F10_t[5] *= d2 * d2 * d2 * d2 * d2;
                F10_t[6] *= d2 * d2 * d2 * d2 * d2 * d2;
            }

            const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
            const auto QC_1 = (a_l * inv_S2) * (r_l[c1] - r_k[c1]);
            const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
            const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

            // i-j Hessian

            const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                        + F10_t[6] * S1 * S1 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                            +PQ[c0]*PQ[c1]*((PB_0*delta[b1][g1] + PB_1*delta[b0][g1])*(PQ[a0]*(PQ[a1]*(PQ[d0]*delta[d1][g0] + PQ[d1]*delta[d0][g0]) + PQ[g0]*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0])) + PQ[a1]*PQ[g0]*(PQ[d0]*delta[a0][d1] + PQ[d1]*delta[a0][d0])) + (PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1])*(PA_0*(PQ[a1]*(PQ[d0]*delta[d1][g0] + PQ[d1]*delta[d0][g0]) + PQ[g0]*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0])) + PA_1*(PQ[a0]*(PQ[d0]*delta[d1][g0] + PQ[d1]*delta[d0][g0]) + PQ[g0]*(PQ[d0]*delta[a0][d1] + PQ[d1]*delta[a0][d0])) + PA_x*(PQ[a0]*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0]) + PQ[a1]*(PQ[d0]*delta[a0][d1] + PQ[d1]*delta[a0][d0])))) + PQ[d0]*PQ[d1]*((PB_0*delta[b1][g1] + PB_1*delta[b0][g1])*(PQ[a0]*(PQ[a1]*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0]) + PQ[g0]*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0])) + PQ[a1]*PQ[g0]*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0])) + (PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1])*(PA_0*(PQ[a1]*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0]) + PQ[g0]*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0])) + PA_1*(PQ[a0]*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0]) + PQ[g0]*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0])) + PA_x*(PQ[a0]*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0]) + PQ[a1]*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0]))))

                            +(PQ[a0]*(PA_1*PQ[g0] + PA_x*PQ[a1])*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1]) + PQ[a1]*PQ[g0]*(PA_0*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1]) + PQ[a0]*(PB_0*delta[b1][g1] + PB_1*delta[b0][g1])))*(PQ[c0]*(PQ[c1]*delta[d0][d1] + PQ[d0]*delta[c1][d1] + PQ[d1]*delta[c1][d0]) + PQ[c1]*(PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0]) + PQ[d0]*PQ[d1]*delta[c0][c1])

                            +PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*(delta[b0][g1]*(PB_1*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0] + PQ[g0]*delta[a0][a1]) + PQ[b1]*(PA_0*delta[a1][g0] + PA_1*delta[a0][g0] + PA_x*delta[a0][a1] - PQ[a0]*delta[a1][g0] - PQ[a1]*delta[a0][g0] - PQ[g0]*delta[a0][a1])) + delta[b1][g1]*(PB_0*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0] + PQ[g0]*delta[a0][a1]) + PQ[b0]*(PA_0*delta[a1][g0] + PA_1*delta[a0][g0] + PA_x*delta[a0][a1] - PQ[a0]*delta[a1][g0] - PQ[a1]*delta[a0][g0] - PQ[g0]*delta[a0][a1])))

                            +PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*(PQ[a0]*(PA_1*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1])) + PQ[a1]*(PA_x*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1]) + (PA_0 - PQ[a0])*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])) + PQ[g0]*(delta[b0][g1]*(delta[a0][b1]*(PA_1 - PQ[a1]) + delta[a1][b1]*(PA_0 - PQ[a0])) + delta[b1][g1]*(delta[a0][b0]*(PA_1 - PQ[a1]) + delta[a1][b0]*(PA_0 - PQ[a0]))))

                            +(PA_1*PQ[a0]*PQ[g0] + PQ[a1]*(PA_0*PQ[g0] + PA_x*PQ[a0]))*(PQ[c0]*PQ[c1]*(PQ[d0]*(delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + PQ[d1]*(delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0])) + PQ[d0]*PQ[d1]*(PQ[c0]*(delta[b0][c1]*delta[b1][g1] + delta[b0][g1]*delta[b1][c1]) + PQ[c1]*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0])))

                        )


                    );

            double hess_ij_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + i] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j_prim],
                hess_ij_xy * ik_factor_D * 2.0 * frac_exact_exchange);
        }
    }

    __syncthreads();
}

__global__ void __launch_bounds__(TILE_SIZE_K)
computeExchangeHessianDDDD_IJ_168(double*         hess_xy,
                                double*         hess_yx,
                                const uint32_t  hess_cart_ind_0,
                                const uint32_t  hess_cart_ind_1,
                                const double    frac_exact_exchange,
                                const uint32_t* pair_inds_i_for_K_dd,
                                const uint32_t* pair_inds_k_for_K_dd,
                                const double*   D_ik_for_K_dd,
                                const uint32_t  pair_inds_count_for_K_dd,
                                const double*   d_prim_info,
                                const uint32_t* d_prim_aoinds,
                                const uint32_t  d_prim_count,
                                const double    dd_max_D,
                                const double*   mat_D_full_AO,
                                const uint32_t  naos,
                                const double*   Q_K_dd,
                                const uint32_t* D_inds_K_dd,
                                const uint32_t* pair_displs_K_dd,
                                const uint32_t* pair_counts_K_dd,
                                const double*   pair_data_K_dd,
                                const uint32_t* prim_cart_ao_to_atom_inds,
                                const uint32_t  natoms,
                                const uint32_t  s_prim_count,
                                const uint32_t  p_prim_count,
                                const double*   boys_func_table,
                                const double*   boys_func_ft,
                                const double    omega,
                                const double    eri_threshold)
{
    // each thread block scans over [i?|k?] and sum up to a primitive K matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ uint32_t i, k, count_i, count_k, displ_i, displ_k;
    __shared__ double   a_i, r_i[3], a_k, r_k[3], ik_factor_D;
    __shared__ uint32_t a0, a1, c0, c1;
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    const uint32_t ik = blockIdx.x;

    // we make sure that ik < pair_inds_count_for_K_dd when calling the kernel

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
        d_cart_inds[3][0] = 1; d_cart_inds[3][1] = 1;
        d_cart_inds[4][0] = 1; d_cart_inds[4][1] = 2;
        d_cart_inds[5][0] = 2; d_cart_inds[5][1] = 2;

        delta[0][0] = 1.0; delta[0][1] = 0.0; delta[0][2] = 0.0;
        delta[1][0] = 0.0; delta[1][1] = 1.0; delta[1][2] = 0.0;
        delta[2][0] = 0.0; delta[2][1] = 0.0; delta[2][2] = 1.0;

        g0 = hess_cart_ind_0;
        g1 = hess_cart_ind_1;

        i = pair_inds_i_for_K_dd[ik];
        k = pair_inds_k_for_K_dd[ik];

        count_i = pair_counts_K_dd[i];
        count_k = pair_counts_K_dd[k];

        displ_i = pair_displs_K_dd[i];
        displ_k = pair_displs_K_dd[k];

        a_i = d_prim_info[i / 6 + d_prim_count * 0];

        r_i[0] = d_prim_info[i / 6 + d_prim_count * 2];
        r_i[1] = d_prim_info[i / 6 + d_prim_count * 3];
        r_i[2] = d_prim_info[i / 6 + d_prim_count * 4];

        a_k = d_prim_info[k / 6 + d_prim_count * 0];

        r_k[0] = d_prim_info[k / 6 + d_prim_count * 2];
        r_k[1] = d_prim_info[k / 6 + d_prim_count * 3];
        r_k[2] = d_prim_info[k / 6 + d_prim_count * 4];

        ik_factor_D = (static_cast<double>(i != k) + 1.0) * D_ik_for_K_dd[ik];

        a0 = d_cart_inds[i % 6][0];
        a1 = d_cart_inds[i % 6][1];
        c0 = d_cart_inds[k % 6][0];
        c1 = d_cart_inds[k % 6][1];
    }

    __syncthreads();

    for (uint32_t m = 0; m < (count_i + TILE_DIM_Y_K - 1) / TILE_DIM_Y_K; m++)
    {
        const uint32_t j = m * TILE_DIM_Y_K + threadIdx.y;

        // sync threads before starting a new scan
        __syncthreads();

        double Q_ij, a_j, r_j[3], S_ij_00, S1, inv_S1;
        double PA_0, PA_1, PB_0, PB_1, PA_x, PB_y;
        uint32_t j_prim, j_cgto, b0, b1;

        if (j < count_i)
        {
            Q_ij   = Q_K_dd[displ_i + j];

            j_prim = D_inds_K_dd[displ_i + j];

            j_cgto = d_prim_aoinds[(j_prim / 6) + d_prim_count * (j_prim % 6)];

            a_j = d_prim_info[j_prim / 6 + d_prim_count * 0];

            r_j[0] = d_prim_info[j_prim / 6 + d_prim_count * 2];
            r_j[1] = d_prim_info[j_prim / 6 + d_prim_count * 3];
            r_j[2] = d_prim_info[j_prim / 6 + d_prim_count * 4];

            S1 = a_i + a_j;
            inv_S1 = 1.0 / S1;

            S_ij_00 = pair_data_K_dd[displ_i + j];

            PA_x = (a_j  * inv_S1) * (r_j[g0] - r_i[g0]);
            PB_y = (-a_i * inv_S1) * (r_j[g1] - r_i[g1]);

            b0 = d_cart_inds[j_prim % 6][0];
            b1 = d_cart_inds[j_prim % 6][1];

            PA_0 = (a_j  * inv_S1) * (r_j[a0] - r_i[a0]);
            PA_1 = (a_j  * inv_S1) * (r_j[a1] - r_i[a1]);
            PB_0 = (-a_i * inv_S1) * (r_j[b0] - r_i[b0]);
            PB_1 = (-a_i * inv_S1) * (r_j[b1] - r_i[b1]);

        }

        for (uint32_t n = 0; n < (count_k + TILE_DIM_X_K - 1) / TILE_DIM_X_K; n++)
        {
            const uint32_t l = n * TILE_DIM_X_K + threadIdx.x;

            // Q_kl == Q_K_dd[displ_k + l]
            if ((j >= count_i) || (l >= count_k) || (fabs(Q_ij * Q_K_dd[displ_k + l] * dd_max_D) <= eri_threshold))
            {
                break;
            }

            // const auto Q_kl = Q_K_dd[displ_k + l];

            const auto l_prim = D_inds_K_dd[displ_k + l];

            const auto l_cgto = d_prim_aoinds[(l_prim / 6) + d_prim_count * (l_prim % 6)];

            const auto a_l = d_prim_info[l_prim / 6 + d_prim_count * 0];

            const double r_l[3] = {d_prim_info[l_prim / 6 + d_prim_count * 2],
                                   d_prim_info[l_prim / 6 + d_prim_count * 3],
                                   d_prim_info[l_prim / 6 + d_prim_count * 4]};

            const auto S_kl_00 = pair_data_K_dd[displ_k + l];

            const auto d0 = d_cart_inds[l_prim % 6][0];
            const auto d1 = d_cart_inds[l_prim % 6][1];

            // J. Chem. Phys. 84, 3963-3974 (1986)

            const auto S2 = a_k + a_l;

            const auto inv_S2 = 1.0 / S2;
            const auto inv_S4 = 1.0 / (S1 + S2);

            const double PQ[3] = {(a_k * r_k[0] + a_l * r_l[0]) * inv_S2 - (a_i * r_i[0] + a_j * r_j[0]) * inv_S1,
                                  (a_k * r_k[1] + a_l * r_l[1]) * inv_S2 - (a_i * r_i[1] + a_j * r_j[1]) * inv_S1,
                                  (a_k * r_k[2] + a_l * r_l[2]) * inv_S2 - (a_i * r_i[2] + a_j * r_j[2]) * inv_S1};

            const auto r2_PQ = PQ[0] * PQ[0] + PQ[1] * PQ[1] + PQ[2] * PQ[2];

            const auto rho = S1 * S2 * inv_S4;

            double d2 = 1.0;

            if (omega != 0.0) d2 = omega * omega / (rho + omega * omega);

            const auto Lambda = sqrt(4.0 * rho * d2 * MATH_CONST_INV_PI);

            double F10_t[7];

            gpu::computeBoysFunction(F10_t, rho * d2 * r2_PQ, 6, boys_func_table, boys_func_ft);

            if (omega != 0.0)
            {
                F10_t[1] *= d2;
                F10_t[2] *= d2 * d2;
                F10_t[3] *= d2 * d2 * d2;
                F10_t[4] *= d2 * d2 * d2 * d2;
                F10_t[5] *= d2 * d2 * d2 * d2 * d2;
                F10_t[6] *= d2 * d2 * d2 * d2 * d2 * d2;
            }

            const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
            const auto QC_1 = (a_l * inv_S2) * (r_l[c1] - r_k[c1]);
            const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
            const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

            // i-j Hessian

            const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                        + F10_t[6] * S1 * S1 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_j * (

                            +PQ[c0]*PQ[c1]*((PA_0*delta[a1][g0] + PA_1*delta[a0][g0])*(PQ[b0]*(PQ[b1]*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1]) + PQ[g1]*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0])) + PQ[b1]*PQ[g1]*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0])) + (PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0])*(PB_0*(PQ[b1]*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1]) + PQ[g1]*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0])) + PB_1*(PQ[b0]*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1]) + PQ[g1]*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0])) + PB_y*(PQ[b0]*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0]) + PQ[b1]*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0])))) + PQ[d0]*PQ[d1]*((PA_0*delta[a1][g0] + PA_1*delta[a0][g0])*(PQ[b0]*(PQ[b1]*(PQ[c0]*delta[c1][g1] + PQ[c1]*delta[c0][g1]) + PQ[g1]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0])) + PQ[b1]*PQ[g1]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0])) + (PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0])*(PB_0*(PQ[b1]*(PQ[c0]*delta[c1][g1] + PQ[c1]*delta[c0][g1]) + PQ[g1]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0])) + PB_1*(PQ[b0]*(PQ[c0]*delta[c1][g1] + PQ[c1]*delta[c0][g1]) + PQ[g1]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0])) + PB_y*(PQ[b0]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0]) + PQ[b1]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0]))))

                            +(PQ[b0]*(PB_1*PQ[g1] + PB_y*PQ[b1])*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0]) + PQ[b1]*PQ[g1]*(PB_0*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0]) + PQ[b0]*(PA_0*delta[a1][g0] + PA_1*delta[a0][g0])))*(PQ[c0]*(PQ[c1]*delta[d0][d1] + PQ[d0]*delta[c1][d1] + PQ[d1]*delta[c1][d0]) + PQ[c1]*(PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0]) + PQ[d0]*PQ[d1]*delta[c0][c1])

                            +PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*(delta[a0][g0]*(PA_1*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PQ[a1]*(PB_0*delta[b1][g1] + PB_1*delta[b0][g1] + PB_y*delta[b0][b1] - PQ[b0]*delta[b1][g1] - PQ[b1]*delta[b0][g1] - PQ[g1]*delta[b0][b1])) + delta[a1][g0]*(PA_0*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PQ[a0]*(PB_0*delta[b1][g1] + PB_1*delta[b0][g1] + PB_y*delta[b0][b1] - PQ[b0]*delta[b1][g1] - PQ[b1]*delta[b0][g1] - PQ[g1]*delta[b0][b1])))

                            +PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*(PQ[b0]*(PB_1*(delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0]) + PB_y*(delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1])) + PQ[b1]*(PB_y*(delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0]) + (PB_0 - PQ[b0])*(delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0])) + PQ[g1]*(delta[a0][g0]*(delta[a1][b0]*(PB_1 - PQ[b1]) + delta[a1][b1]*(PB_0 - PQ[b0])) + delta[a1][g0]*(delta[a0][b0]*(PB_1 - PQ[b1]) + delta[a0][b1]*(PB_0 - PQ[b0]))))

                            +(PB_1*PQ[b0]*PQ[g1] + PQ[b1]*(PB_0*PQ[g1] + PB_y*PQ[b0]))*(PQ[c0]*PQ[c1]*(PQ[d0]*(delta[a0][d1]*delta[a1][g0] + delta[a0][g0]*delta[a1][d1]) + PQ[d1]*(delta[a0][d0]*delta[a1][g0] + delta[a0][g0]*delta[a1][d0])) + PQ[d0]*PQ[d1]*(PQ[c0]*(delta[a0][c1]*delta[a1][g0] + delta[a0][g0]*delta[a1][c1]) + PQ[c1]*(delta[a0][c0]*delta[a1][g0] + delta[a0][g0]*delta[a1][c0])))

                        )


                    );

            double hess_ij_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + i] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j_prim],
                hess_ij_xy * ik_factor_D * 2.0 * frac_exact_exchange);
        }
    }

    __syncthreads();
}

__global__ void __launch_bounds__(TILE_SIZE_K)
computeExchangeHessianDDDD_IJ_169(double*         hess_xy,
                                double*         hess_yx,
                                const uint32_t  hess_cart_ind_0,
                                const uint32_t  hess_cart_ind_1,
                                const double    frac_exact_exchange,
                                const uint32_t* pair_inds_i_for_K_dd,
                                const uint32_t* pair_inds_k_for_K_dd,
                                const double*   D_ik_for_K_dd,
                                const uint32_t  pair_inds_count_for_K_dd,
                                const double*   d_prim_info,
                                const uint32_t* d_prim_aoinds,
                                const uint32_t  d_prim_count,
                                const double    dd_max_D,
                                const double*   mat_D_full_AO,
                                const uint32_t  naos,
                                const double*   Q_K_dd,
                                const uint32_t* D_inds_K_dd,
                                const uint32_t* pair_displs_K_dd,
                                const uint32_t* pair_counts_K_dd,
                                const double*   pair_data_K_dd,
                                const uint32_t* prim_cart_ao_to_atom_inds,
                                const uint32_t  natoms,
                                const uint32_t  s_prim_count,
                                const uint32_t  p_prim_count,
                                const double*   boys_func_table,
                                const double*   boys_func_ft,
                                const double    omega,
                                const double    eri_threshold)
{
    // each thread block scans over [i?|k?] and sum up to a primitive K matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ uint32_t i, k, count_i, count_k, displ_i, displ_k;
    __shared__ double   a_i, r_i[3], a_k, r_k[3], ik_factor_D;
    __shared__ uint32_t a0, a1, c0, c1;
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    const uint32_t ik = blockIdx.x;

    // we make sure that ik < pair_inds_count_for_K_dd when calling the kernel

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
        d_cart_inds[3][0] = 1; d_cart_inds[3][1] = 1;
        d_cart_inds[4][0] = 1; d_cart_inds[4][1] = 2;
        d_cart_inds[5][0] = 2; d_cart_inds[5][1] = 2;

        delta[0][0] = 1.0; delta[0][1] = 0.0; delta[0][2] = 0.0;
        delta[1][0] = 0.0; delta[1][1] = 1.0; delta[1][2] = 0.0;
        delta[2][0] = 0.0; delta[2][1] = 0.0; delta[2][2] = 1.0;

        g0 = hess_cart_ind_0;
        g1 = hess_cart_ind_1;

        i = pair_inds_i_for_K_dd[ik];
        k = pair_inds_k_for_K_dd[ik];

        count_i = pair_counts_K_dd[i];
        count_k = pair_counts_K_dd[k];

        displ_i = pair_displs_K_dd[i];
        displ_k = pair_displs_K_dd[k];

        a_i = d_prim_info[i / 6 + d_prim_count * 0];

        r_i[0] = d_prim_info[i / 6 + d_prim_count * 2];
        r_i[1] = d_prim_info[i / 6 + d_prim_count * 3];
        r_i[2] = d_prim_info[i / 6 + d_prim_count * 4];

        a_k = d_prim_info[k / 6 + d_prim_count * 0];

        r_k[0] = d_prim_info[k / 6 + d_prim_count * 2];
        r_k[1] = d_prim_info[k / 6 + d_prim_count * 3];
        r_k[2] = d_prim_info[k / 6 + d_prim_count * 4];

        ik_factor_D = (static_cast<double>(i != k) + 1.0) * D_ik_for_K_dd[ik];

        a0 = d_cart_inds[i % 6][0];
        a1 = d_cart_inds[i % 6][1];
        c0 = d_cart_inds[k % 6][0];
        c1 = d_cart_inds[k % 6][1];
    }

    __syncthreads();

    for (uint32_t m = 0; m < (count_i + TILE_DIM_Y_K - 1) / TILE_DIM_Y_K; m++)
    {
        const uint32_t j = m * TILE_DIM_Y_K + threadIdx.y;

        // sync threads before starting a new scan
        __syncthreads();

        double Q_ij, a_j, r_j[3], S_ij_00, S1, inv_S1;
        double PA_0, PA_1, PB_0, PB_1, PA_x, PB_y;
        uint32_t j_prim, j_cgto, b0, b1;

        if (j < count_i)
        {
            Q_ij   = Q_K_dd[displ_i + j];

            j_prim = D_inds_K_dd[displ_i + j];

            j_cgto = d_prim_aoinds[(j_prim / 6) + d_prim_count * (j_prim % 6)];

            a_j = d_prim_info[j_prim / 6 + d_prim_count * 0];

            r_j[0] = d_prim_info[j_prim / 6 + d_prim_count * 2];
            r_j[1] = d_prim_info[j_prim / 6 + d_prim_count * 3];
            r_j[2] = d_prim_info[j_prim / 6 + d_prim_count * 4];

            S1 = a_i + a_j;
            inv_S1 = 1.0 / S1;

            S_ij_00 = pair_data_K_dd[displ_i + j];

            PA_x = (a_j  * inv_S1) * (r_j[g0] - r_i[g0]);
            PB_y = (-a_i * inv_S1) * (r_j[g1] - r_i[g1]);

            b0 = d_cart_inds[j_prim % 6][0];
            b1 = d_cart_inds[j_prim % 6][1];

            PA_0 = (a_j  * inv_S1) * (r_j[a0] - r_i[a0]);
            PA_1 = (a_j  * inv_S1) * (r_j[a1] - r_i[a1]);
            PB_0 = (-a_i * inv_S1) * (r_j[b0] - r_i[b0]);
            PB_1 = (-a_i * inv_S1) * (r_j[b1] - r_i[b1]);

        }

        for (uint32_t n = 0; n < (count_k + TILE_DIM_X_K - 1) / TILE_DIM_X_K; n++)
        {
            const uint32_t l = n * TILE_DIM_X_K + threadIdx.x;

            // Q_kl == Q_K_dd[displ_k + l]
            if ((j >= count_i) || (l >= count_k) || (fabs(Q_ij * Q_K_dd[displ_k + l] * dd_max_D) <= eri_threshold))
            {
                break;
            }

            // const auto Q_kl = Q_K_dd[displ_k + l];

            const auto l_prim = D_inds_K_dd[displ_k + l];

            const auto l_cgto = d_prim_aoinds[(l_prim / 6) + d_prim_count * (l_prim % 6)];

            const auto a_l = d_prim_info[l_prim / 6 + d_prim_count * 0];

            const double r_l[3] = {d_prim_info[l_prim / 6 + d_prim_count * 2],
                                   d_prim_info[l_prim / 6 + d_prim_count * 3],
                                   d_prim_info[l_prim / 6 + d_prim_count * 4]};

            const auto S_kl_00 = pair_data_K_dd[displ_k + l];

            const auto d0 = d_cart_inds[l_prim % 6][0];
            const auto d1 = d_cart_inds[l_prim % 6][1];

            // J. Chem. Phys. 84, 3963-3974 (1986)

            const auto S2 = a_k + a_l;

            const auto inv_S2 = 1.0 / S2;
            const auto inv_S4 = 1.0 / (S1 + S2);

            const double PQ[3] = {(a_k * r_k[0] + a_l * r_l[0]) * inv_S2 - (a_i * r_i[0] + a_j * r_j[0]) * inv_S1,
                                  (a_k * r_k[1] + a_l * r_l[1]) * inv_S2 - (a_i * r_i[1] + a_j * r_j[1]) * inv_S1,
                                  (a_k * r_k[2] + a_l * r_l[2]) * inv_S2 - (a_i * r_i[2] + a_j * r_j[2]) * inv_S1};

            const auto r2_PQ = PQ[0] * PQ[0] + PQ[1] * PQ[1] + PQ[2] * PQ[2];

            const auto rho = S1 * S2 * inv_S4;

            double d2 = 1.0;

            if (omega != 0.0) d2 = omega * omega / (rho + omega * omega);

            const auto Lambda = sqrt(4.0 * rho * d2 * MATH_CONST_INV_PI);

            double F10_t[7];

            gpu::computeBoysFunction(F10_t, rho * d2 * r2_PQ, 6, boys_func_table, boys_func_ft);

            if (omega != 0.0)
            {
                F10_t[1] *= d2;
                F10_t[2] *= d2 * d2;
                F10_t[3] *= d2 * d2 * d2;
                F10_t[4] *= d2 * d2 * d2 * d2;
                F10_t[5] *= d2 * d2 * d2 * d2 * d2;
                F10_t[6] *= d2 * d2 * d2 * d2 * d2 * d2;
            }

            const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
            const auto QC_1 = (a_l * inv_S2) * (r_l[c1] - r_k[c1]);
            const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
            const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

            // i-j Hessian

            const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

