                            +PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*(PQ[a0]*(PA_1*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + PB_0*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PB_1*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + PB_y*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) - 2*PQ[a1]*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) - 2*PQ[b0]*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) - 2*PQ[b1]*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) - 2*PQ[g0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) - 2*PQ[g1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1])) + PQ[a1]*(PA_0*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) + PB_0*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + PB_1*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) + PB_y*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]) - 2*PQ[b0]*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) - 2*PQ[b1]*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) - 2*PQ[g0]*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) - 2*PQ[g1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])) + PQ[b0]*(PA_0*(delta[a1][b1]*delta[g0][g1] + d