ta[c0][g1]) + PQ[g1]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0])) + PB_1*(PQ[c0]*(PQ[g0]*delta[c1][g1] + PQ[g1]*delta[c1][g0]) + PQ[c1]*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0])) + PB_y*(PQ[b1]*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0]) + PQ[g0]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0]))) + PQ[b1]*(PA_0*(PQ[c0]*(PQ[g0]*delta[c1][g1] + PQ[g1]*delta[c1][g0]) + PQ[c1]*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0])) + (PA_x*PQ[g1] + PB_y*PQ[g0])*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0]))) + PQ[g0]*PQ[g1]*(PQ[a0]*(PA_1*(PQ[b0]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0]) + PQ[b1]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0])) + PB_0*(PQ[a1]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0]) + PQ[b1]*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0])) + PB_1*(PQ[a1]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0]) + PQ[b0]*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0]))) + PQ[a1]*(PA_0*(PQ[b0]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0]) + PQ[b1]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0])) + (PB_0*PQ[b1] + PB_1*PQ[b0])*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0])) + PQ[b0]*PQ[b1]*(PA_0*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0]) + PA_1*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0]))))

