                F10_t[2] *= d2 * d2;
                F10_t[3] *= d2 * d2 * d2;
                F10_t[4] *= d2 * d2 * d2 * d2;
                F10_t[5] *= d2 * d2 * d2 * d2 * d2;
                F10_t[6] *= d2 * d2 * d2 * d2 * d2 * d2;
                F10_t[7] *= d2 * d2 * d2 * d2 * d2 * d2 * d2;
                F10_t[8] *= d2 * d2 * d2 * d2 * d2 * d2 * d2 * d2;
                F10_t[9] *= d2 * d2 * d2 * d2 * d2 * d2 * d2 * d2 * d2;
                F10_t[10] *= d2 * d2 * d2 * d2 * d2 * d2 * d2 * d2 * d2 * d2;
            }

