                            +(QD_0*(QD_1*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + QD_y*(delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1])) + QD_1*QD_y*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]))*(PA_0*(PA_1*delta[b0][b1] + PB_0*delta[a1][b1] + PB_1*delta[a1][b0]) - PA_0*(PQ[a1]*delta[b0][b1] + PQ[b0]*delta[a1][b1] + PQ[b1]*delta[a1][b0]) + PA_1*(PB_0*delta[a0][b1] + PB_1*delta[a0][b0]) - PA_1*(PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0]) + PB_0*PB_1*delta[a0][a1] - PB_0*(PQ[a0]*delta[a1][b1] + PQ[a1]*delta[a0][b1] + PQ[b1]*delta[a0][a1]) - PB_1*(PQ[a0]*delta[a1][b0] + PQ[a1]*delta[a0][b0] + PQ[b0]*delta[a0][a1]))

                            -(QC_0*delta[c1][g0] + QC_1*delta[c0][g0])*(QD_0*(QD_1*(PA_0*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + PA_1*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) + PB_0*(delta[a0][a1]*delta[b1][g1] + delta[a0][b1]*delta[a1][g1] + delta[a0][g1]*delta[a1][b1]) + PB_1*(delta[a0][a1]*delta[b0][g1] + delta[a0][b0]*delta[a1][g1] + delta[a0][g1]*delta[a1][b0])) + QD_y*(PA_0*(delta[a1][b0]*delta[b1][d1] + delta[a1][b1]*delta[b0][d1] + delta[a1][d1]*delta[b0][b1]) + PA_1*(delta[a0][b0]*delta[b1][d1] + delta[a0][b1]*delta[b0][d1] + delta[a0][d1]*delta[b0][b1]) + PB_0*(delta[a0][a1]*delta[b1][d1] + delta[a0][b1]*delta[a1][d1] + delta[a0][d1]*delta[a1][b1]) + PB_1*(delta[a0][a1]*delta[b0][d1] + delta[a0][b0]*delta[a1][d1] + delta[a0][d1]*delta[a1][b0]))) + QD_1*QD_y*(PA_0*(delta[a1][b0]*delta[b1][d0] + delta[a1][b1]*delta[b0][d0] + delta[a1][d0]*delta[b0][b1]) + PA_1*(delta[a0][b0]*delta[b1][d0] + delta[a0][b1]*delta[b0][d0] + delta[a0][d0]*delta[b0][b1]) + PB_0*(delta[a0][a1]*delta[b1][d0] + delta[a0][b1]*delta[a1][d0] + delta[a0][d0]*delta[a1][b1]) + PB_1*(delta[a0][a1]*delta[b0][d0] + delta[a0][b0]*delta[a1][d0] + delta[a0][d0]*delta[a1][b0])))

