                            +(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0])*(PQ[d1]*(QC_0*(PQ[g0]*(QC_1*delta[d0][g1] + QD_0*delta[c1][g1]) + PQ[g1]*(QC_1*delta[d0][g0] + QC_x*delta[c1][d0] + QD_0*delta[c1][g0])) + QC_1*(QC_x*(PQ[g1]*delta[c0][d0] + delta[d0][g1]*(PQ[c0] + QC_0)) + QD_0*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0] + delta[g0][g1]*(PQ[c0] + QC_0)) + QD_y*delta[d0][g0]*(PQ[c0] + QC_0)) + QD_0*(QC_x*(PQ[g1]*delta[c0][c1] + delta[c0][g1]*(PQ[c1] + QC_1) + delta[c1][g1]*(PQ[c0] + QC_0)) + QD_y*(delta[c0][c1]*(PQ[g0] + QC_x) + delta[c0][g0]*(PQ[c1] + QC_1) + delta[c1][g0]*(PQ[c0] + QC_0))) + QD_y*(PQ[g0] + QC_x)*(QC_0*delta[c1][d0] + QC_1*delta[c0][d0])) + PQ[g0]*PQ[g1]*(QC_0*(QC_1*delta[d0][d1] + QD_0*delta[c1][d1] + QD_1*delta[c1][d0]) + QC_1*(QD_0*delta[c0][d1] + QD_1*delta[c0][d0])) + QC_0*(PQ[c1]*(QC_x*(PQ[g1]*delta[d0][d1] + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + QD_0*(PQ[d1]*delta[g0][g1] + PQ[g0]*delta[d1][g1] + PQ[g1]*delta[d1][g0]) + QD_1*(PQ[g0]*delta[d0][g1] + PQ[g1]*delta[d0][g0] + delta[g0][g1]*(PQ[d0] + QD_0)) + QD_y*(delta[d0][d1]*(PQ[g0] + QC_x) + delta[d0][g0]*(PQ[d1] + QD_1) + delta[d1][g0]*(PQ[d0] + QD_0))) + PQ[d0]*(QC_1*(PQ[d1]*delta[g0][g1] + PQ[g0]*delta[d1][g1] + PQ[g1]*delta[d1][g0]) + QC_x*(PQ[g1]*delta[c1][d1] + delta[c1][g1]*(PQ[d1] + QD_1)) + QD_1*(PQ[g0]*delta[c1][g1] + PQ[g1]*delta[c1][g0]) + QD_y*(delta[c1][d1]*(PQ[g0] + QC_x) + delta[c1][g0]*(PQ[d1] + QD_1)))) + QC_1*(PQ[d0]*(QC_x*(PQ[g1]*delta[c0][d1] + delta[c0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[c0] + QC_0)) + QD_1*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0] + delta[g0][g1]*(PQ[c0] + QC_0)) + QD_y*(delta[c0][d1]*(PQ[g0] + QC_x) + delta[c0][g0]*(PQ[d1] + QD_1) + delta[d1][g0]*(PQ[c0] + QC_0))) + (PQ[c0] + QC_0)*(PQ[g0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1] + QD_y*delta[d0][d1]) + PQ[g1]*(QC_x*delta[d0][d1] + QD_0*delta[d1][g0] + QD_1*delta[d0][g0]))) + QC_x*(PQ[c0]*(QD_1*(delta[c1][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c1] + QC_1)) + QD_y*(delta[c1][d0]*(PQ[d1] + QD_1) + delta[c1][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c1] + QC_1))) + PQ[c1]*(PQ[d0] + QD_0)*(QD_1*delta[c0][g1] + QD_y*delta[c0][d1]) + PQ[g1]*(QD_0*(delta[c0][d1]*(PQ[c1] + QC_1) + delta[c1][d1]*(PQ[c0] + QC_0)) + QD_1*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0))) + QD_y*(PQ[d1] + QD_1)*(PQ[c1]*delta[c0][d0] + PQ[d0]*delta[c0][c1])) + QD_0*(PQ[c0]*(PQ[c1] + QC_1)*(QC_x*delta[d1][g1] + QD_1*delta[g0][g1] + QD_y*delta[d1][g0]) + PQ[g0]*(QD_1*(PQ[g1]*delta[c0][c1] + delta[c0][g1]*(PQ[c1] + QC_1) + delta[c1][g1]*(PQ[c0] + QC_0)) + QD_y*(delta[c0][d1]*(PQ[c1] + QC_1) + delta[c1][d1]*(PQ[c0] + QC_0))) + PQ[g1]*QD_1*(delta[c0][g0]*(PQ[c1] + QC_1) + delta[c1][g0]*(PQ[c0] + QC_0))) + QD_1*QD_y*(PQ[c0]*(delta[c1][g0]*(PQ[d0] + QD_0) + delta[d0][g0]*(PQ[c1] + QC_1)) + PQ[c1]*delta[c0][g0]*(PQ[d0] + QD_0) + PQ[g0]*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0))))

                        )


                    );

            double hess_kl_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + k] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + l_prim],
                hess_kl_xy * ik_factor_D * 2.0 * frac_exact_exchange);
        }
    }

