            const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                        + F10_t[2] * (-2.0) * S1 * S1 * inv_S4 * inv_S4 * a_k * (

                            +PA_0*PA_1*PB_0*PB_1*(PQ[c0]*QC_x*(PQ[c1]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + QC_1*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1])) + PQ[c1]*QC_0*(PQ[g0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + QC_x*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1])) + PQ[g0]*QC_1*(PQ[c0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + QC_0*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1])))

