(delta[a1][b0]*(delta[b1][c1]*delta[d0][g0] + delta[b1][d0]*delta[c1][g0] + delta[b1][g0]*delta[c1][d0]) + delta[a1][b1]*(delta[b0][c1]*delta[d0][g0] + delta[b0][d0]*delta[c1][g0] + delta[b0][g0]*delta[c1][d0]) + delta[b0][b1]*(delta[a1][c1]*delta[d0][g0] + delta[a1][d0]*delta[c1][g0] + delta[a1][g0]*delta[c1][d0])) + PA_1*(delta[a0][b0]*(delta[b1][c1]*delta[d0][g0] + delta[b1][d0]*delta[c1][g0] + delta[b1][g0]*delta[c1][d0]) + delta[a0][b1]*(delta[b0][c1]*delta[d0][g0] + delta[b0][d0]*delta[c1][g0] + delta[b0][g0]*delta[c1][d0]) + delta[b0][b1]*(delta[a0][c1]*delta[d0][g0] + delta[a0][d0]*delta[c1][g0] + delta[a0][g0]*delta[c1][d0])) + PB_0*(delta[a0][a1]*(delta[b1][c1]*delta[d0][g0] + delta[b1][d0]*delta[c1][g0] + delta[b1][g0]*delta[c1][d0]) + delta[a0][b1]*(delta[a1][c1]*delta[d0][g0] + delta[a1][d0]*delta[c1][g0] + delta[a1][g0]*delta[c1][d0]) + delta[a1][b1]*(delta[a0][c1]*delta[d0][g0] + delta[a0][d0]*delta[c1][g0] + delta[a0][g0]*delta[c1][d0])) + PB_1*(delta[a0][a1]*(delta[b0][c1]*delta[d0][g0] + delta[b0][d0]*delta[c1][g0] + delta[b0][g0]*delta[c1][d0]) + delta[a0][b0]*(delta[a1][c1]*delta[d0][g0] + delta[a1][d0]*delta[c1][g0] + delta[a1][g0]*delta[c1][d0]) + delta[a1][b0]*(delta[a0][c1]*delta[d0][g0] + delta[a0][d0]*delta[c1][g0] + delta[a0][g0]*delta[c1][d0]))) + PQ[c1]*(PA_0*(delta[a1][b0]*(delta[b1][c0]*delta[d0][g0] + delta[b1][d0]*delta[c0][g0] + delta[b1][g0]*delta[c0][d0]) + delta[a1][b1]*(delta[b0][c0]*delta[d0][g0] + delta[b0][d0]*delta[c0][g0] + delta[b0][g0]*delta[c0][d0]) + delta[b0][b1]*(delta[a1][c0]*delta[d0][g0] + delta[a1][d0]*delta[c0][g0] + delta[a1][g0]*delta[c0][d0])) + PA_1*(delta[a0][b0]*(delta[b1][c0]*delta[d0][g0] + delta[b1][d0]*delta[c0][g0] + delta[b1][g0]*delta[c0][d0]) + delta[a0][b1]*(delta[b0][c0]*delta[d0][g0] + delta[b0][d0]*delta[c0][g0] + delta[b0][g0]*delta[c0][d0]) + delta[b0][b1]*(delta[a0][c0]*delta[d0][g0] + delta[a0][d0]*delta[c0][g0] + delta[a0][g0]*delta[c0][d0])) + PB_0*(delta[a0][a1]*(delta[b1][c0]*delta[d0][g0] + delta[b1][d0]*delta[c0][g0] + delta[b1][g0]*delta[c0][d0]) + delta[a0][b1]*(delta[a1][c0]*delta[d0][g0] + delta[a1][d0]*delta[c0][g0] + delta[a1][g0]*delta[c0][d0]) + delta[a1][b1]*(delta[a0][c0]*delta[d0][g0] + delta[a0][d0]*delta[c0][g0] + delta[a0][g0]*delta[c0][d0])) + PB_1*(delta[a0][a1]*(delta[b0][c0]*delta[d0][g0] + delta[b0][d0]*delta[c0][g0] + delta[b0][g0]*delta[c0][d0]) + delta[a0][b0]*(delta[a1][c0]*delta[d0][g0] + delta[a1][d0]*delta[c0][g0] + delta[a1][g0]*delta[c0][d0]) + delta[a1][b0]*(delta[a0][c0]*delta[d0][g0] + delta[a0][d0]*delta[c0][g0] + delta[a0][g0]*delta[c0][d0]))) + PQ[g0]*(PA_0*(delta[a1][b0]*(delta[b1][c0]*delta[c1][d0] + delta[b1][c1]*delta[c0][d0] + delta[b1][d0]*delta[c0][c1]) + delta[a1][b1]*(delta[b0][c0]*delta[c1][d0] + delta[b0][c1]*delta[c0][d0] + delta[b0][d0]*delta[c0][c1]) + delta[b0][b1]*(delta[a1][c0]*delta[c1][d0] + delta[a1][c1]*delta[c0][d0] + delta[a1][d0]*delta[c0][c1])) + PA_1*(delta[a0][b0]*(delta[b1][c0]*delta[c1][d0] + delta[b1][c1]*delta[c0][d0] + delta[b1][d0]*delta[c0][c1]) + delta[a0][b1]*(delta[b0][c0]*delta[c1][d0] + delta[b0][c1]*delta[c0][d0] + delta[b0][d0]*delta[c0][c1]) + delta[b0][b1]*(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1])) + PB_0*(delta[a0][a1]*(delta[b1][c0]*delta[c1][d0] + delta[b1][c1]*delta[c0][d0] + delta[b1][d0]*delta[c0][c1]) + delta[a0][b1]*(delta[a1][c0]*delta[c1][d0] + delta[a1][c1]*delta[c0][d0] + delta[a1][d0]*delta[c0][c1]) + delta[a1][b1]*(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1])) + PB_1*(delta[a0][a1]*(delta[b0][c0]*delta[c1][d0] + delta[b0][c1]*delta[c0][d0] + delta[b0][d0]*delta[c0][c1]) + delta[a0][b0]*(delta[a1][c0]*delta[c1][d0] + delta[a1][c1]*delta[c0][d0] + delta[a1][d0]*delta[c0][c1]) + delta[a1][b0]*(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1]))))

                            -(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1])*(PA_0*(delta[a1][b0]*(delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0] + delta[b1][g0]*delta[c0][c1]) + delta[a1][b1]*(delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0] + delta[b0][g0]*delta[c0][c1]) + delta[b0][b1]*(delta[a1][c0]*delta[c1][g0] + delta[a1][c1]*delta[c0][g0] + delta[a1][g0]*delta[c0][c1])) + PA_1*(delta[a0][b0]*(delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0] + delta[b1][g0]*delta[c0][c1]) + delta[a0][b1]*(delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0] + delta[b0][g0]*delta[c0][c1]) + delta[b0][b1]*(delta[a0][c0]*delta[c1][g0] + delta[a0][c1]*delta[c0][g0] + delta[a0][g0]*delta[c0][c1])) + PB_0*(delta[a0][a1]*(delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0] + delta[b1][g0]*delta[c0][c1]) + delta[a0][b1]*(delta[a1][c0]*delta[c1][g0] + delta[a1][c1]*delta[c0][g0] + delta[a1][g0]*delta[c0][c1]) + delta[a1][b1]*(delta[a0][c0]*delta[c1][g0] + delta[a0][c1]*delta[c0][g0] + delta[a0][g0]*delta[c0][c1])) + PB_1*(delta[a0][a1]*(delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0] + delta[b0][g0]*delta[c0][c1]) + delta[a0][b0]*(delta[a1][c0]*delta[c1][g0] + delta[a1][c1]*delta[c0][g0] + delta[a1][g0]*delta[c0][c1]) + delta[a1][b0]*(delta[a0][c0]*delta[c1][g0] + delta[a0][c1]*delta[c0][g0] + delta[a0][g0]*delta[c0][c1])))

                            +(PQ[c0]*(PQ[c1]*(delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + PQ[g0]*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1])) + PQ[c1]*PQ[g0]*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1]))*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0])

                            +(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1])*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0] + PQ[g0]*delta[c0][c1])*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0])

                        )


                    );

            double hess_kl_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + k] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + l_prim],
                hess_kl_xy * ik_factor_D * 2.0 * frac_exact_exchange);
