                            -(PA_0*PA_1*delta[b0][b1] + PA_0*PB_0*delta[a1][b1] + PA_0*PB_1*delta[a1][b0] + PA_1*PB_0*delta[a0][b1] + PA_1*PB_1*delta[a0][b0] + PB_0*PB_1*delta[a0][a1])*(PQ[c0]*PQ[c1]*PQ[d0]*QC_x*delta[d1][g1] + PQ[c0]*PQ[c1]*PQ[d0]*QD_1*delta[g0][g1] + PQ[c0]*PQ[c1]*PQ[d0]*QD_y*delta[d1][g0] + PQ[c0]*PQ[c1]*PQ[d1]*QC_x*delta[d0][g1] + PQ[c0]*PQ[c1]*PQ[d1]*QD_0*delta[g0][g1] + PQ[c0]*PQ[c1]*PQ[d1]*QD_y*delta[d0][g0] + PQ[c0]*PQ[c1]*PQ[g0]*QD_0*delta[d1][g1] + PQ[c0]*PQ[c1]*PQ[g0]*QD_1*delta[d0][g1] + PQ[c0]*PQ[c1]*PQ[g0]*QD_y*delta[d0][d1] + PQ[c0]*PQ[c1]*PQ[g1]*QC_x*delta[d0][d1] + PQ[c0]*PQ[c1]*PQ[g1]*QD_0*delta[d1][g0] + PQ[c0]*PQ[c1]*PQ[g1]*QD_1*delta[d0][g0] + PQ[c0]*PQ[c1]*QC_x*QD_0*delta[d1][g1] + PQ[c0]*PQ[c1]*QC_x*QD_1*delta[d0][g1] + PQ[c0]*PQ[c1]*QC_x*QD_y*delta[d0][d1] + PQ[c0]*PQ[c1]*QD_0*QD_1*delta[g0][g1] + PQ[c0]*PQ[c1]*QD_0*QD_y*delta[d1][g0] + PQ[c0]*PQ[c1]*QD_1*QD_y*delta[d0][g0] + PQ[c0]*PQ[d0]*PQ[d1]*QC_1*delta[g0][g1] + PQ[c0]*PQ[d0]*PQ[d1]*QC_x*delta[c1][g1] + PQ[c0]*PQ[d0]*PQ[d1]*QD_y*delta[c1][g0] + PQ[c0]*PQ[d0]*PQ[g0]*QC_1*delta[d1][g1] + PQ[c0]*PQ[d0]*PQ[g0]*QD_1*delta[c1][g1] + PQ[c0]*PQ[d0]*PQ[g0]*QD_y*delta[c1][d1] + PQ[c0]*PQ[d0]*PQ[g1]*QC_1*delta[d1][g0] + PQ[c0]*PQ[d0]*PQ[g1]*QC_x*delta[c1][d1] + PQ[c0]*PQ[d0]*PQ[g1]*QD_1*delta[c1][g0] + PQ[c0]*PQ[d0]*QC_1*QC_x*delta[d1][g1] + PQ[c0]*PQ[d0]*QC_1*QD_1*delta[g0][g1] + PQ[c0]*PQ[d0]*QC_1*QD_y*delta[d1][g0] + PQ[c0]*PQ[d0]*QC_x*QD_1*delta[c1][g1] + PQ[c0]*PQ[d0]*QC_x*QD_y*delta[c1][d1] + PQ[c0]*PQ[d0]*QD_1*QD_y*delta[c1][g0] + PQ[c0]*PQ[d1]*PQ[g0]*QC_1*delta[d0][g1] + PQ[c0]*PQ[d1]*PQ[g0]*QD_0*delta[c1][g1] + PQ[c0]*PQ[d1]*PQ[g0]*QD_y*delta[c1][d0] + PQ[c0]*PQ[d1]*PQ[g1]*QC_1*delta[d0][g0] + PQ[c0]*PQ[d1]*PQ[g1]*QC_x*delta[c1][d0] + PQ[c0]*PQ[d1]*PQ[g1]*QD_0*delta[c1][g0] + PQ[c0]*PQ[d1]*QC_1*QC_x*delta[d0][g1] + PQ[c0]*PQ[d1]*QC_1*QD_0*delta[g0][g1] + PQ[c0]*PQ[d1]*QC_1*QD_y*delta[d0][g0] + PQ[c0]*PQ[d1]*QC_x*QD_0*delta[c1][g1] + PQ[c0]*PQ[d1]*QC_x*QD_y*delta[c1][d0] + 