                        )

                        + F10_t[3] * S1 * S1 * S1 * inv_S2 * inv_S4 * inv_S4 * inv_S4 * a_l * (

                            +PA_0*PA_1*PB_0*PB_1*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0])*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1] + PQ[g1]*delta[d0][d1])

                            +PA_0*PA_1*PB_0*PB_1*(PQ[d0]*(PQ[d1]*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + PQ[g1]*(delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1])) + PQ[d1]*PQ[g1]*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]))

