lta[b0][c0] + PQ[b0]*delta[a1][c0])) + PA_1*(PB_0*(PQ[a0]*delta[b1][c0] + PQ[b1]*delta[a0][c0]) + PB_1*(PQ[a0]*delta[b0][c0] + PQ[b0]*delta[a0][c0])) + PB_0*PB_1*(PQ[a0]*delta[a1][c0] + PQ[a1]*delta[a0][c0])) + (PQ[c0]*QC_x + PQ[g0]*QC_0)*(PA_0*(PA_1*(PQ[b0]*(QD_1*delta[b1][g1] + QD_y*delta[b1][d1]) + PQ[b1]*(QD_1*delta[b0][g1] + QD_y*delta[b0][d1])) + PB_0*(PQ[a1]*(QD_1*delta[b1][g1] + QD_y*delta[b1][d1]) + PQ[b1]*(QD_1*delta[a1][g1] + QD_y*delta[a1][d1])) + PB_1*(PQ[a1]*(QD_1*delta[b0][g1] + QD_y*delta[b0][d1]) + PQ[b0]*(QD_1*delta[a1][g1] + QD_y*delta[a1][d1]))) + PA_1*(PB_0*(PQ[a0]*(QD_1*delta[b1][g1] + QD_y*delta[b1][d1]) + PQ[b1]*(QD_1*delta[a0][g1] + QD_y*delta[a0][d1])) + PB_1*(PQ[a0]*(QD_1*delta[b0][g1] + QD_y*delta[b0][d1]) + PQ[b0]*(QD_1*delta[a0][g1] + QD_y*delta[a0][d1]))) + PB_0*PB_1*(PQ[a0]*(QD_1*delta[a1][g1] + QD_y*delta[a1][d1]) + PQ[a1]*(QD_1*delta[a0][g1] + QD_y*delta[a0][d1]))))) - QD_1*QD_y*(PQ[c0]*QC_1*(PA_0*(PA_1*(PQ[b0]*(QC_x*delta[b1][d0] + QD_0*delta[b1][g0]) + PQ[b1]*(QC_x*delta[b0][d0] + QD_0*delta[b0][g0])) + PB_0*(PQ[a1]*(QC_x*delta[b1][d0] + QD_0*delta[b1][g0]) + PQ[b1]*(QC_x*delta[a1][d0] + QD_0*delta[a1][g0])) + PB_1*(PQ[a1]*(QC_x*delta[b0][d0] + QD_0*delta[b0][g0]) + PQ[b0]*(QC_x*delta[a1][d0] + QD_0*delta[a1][g0]))) + PA_1*(PB_0*(PQ[a0]*(QC_x*delta[b1][d0] + QD_0*delta[b1][g0]) + PQ[b1]*(QC_x*delta[a0][d0] + QD_0*delta[a0][g0])) + PB_1*(PQ[a0]*(QC_x*delta[b0][d0] + QD_0*delta[b0][g0]) + PQ[b0]*(QC_x*delta[a0][d0] + QD_0*delta[a0][g0]))) + PB_0*PB_1*(PQ[a0]*(QC_x*delta[a1][d0] + QD_0*delta[a1][g0]) + PQ[a1]*(QC_x*delta[a0][d0] + QD_0*delta[a0][g0]))) + QC_0*(PA_0*(PA_1*(PQ[b0]*(PQ[c1]*(QC_x*delta[b1][d0] + QD_0*delta[b1][g0]) + PQ[d0]*(QC_1*delta[b1][g0] + QC_x*delta[b1][c1]) + PQ[g0]*(QC_1*delta[b1][d0] + QD_0*delta[b1][c1])) + PQ[b1]*(PQ[c1]*(QC_x*delta[b0][d0] + QD_0*delta[b0][g0]) + PQ[d0]*(QC_1*delta[b0][g0] + QC_x*delta[b0][c1]) + PQ[g0]*(QC_1*delta[b0][d0] + QD_0*delta[b0][c1]))) + PB_0*(PQ[a1]*(PQ[c1]*(QC_x*delta[b1][d0] + QD_0*delta[b1][g0]) + PQ[d0]*(QC_1*delta[b1][g0] + QC_x*delta[b1][c1]) + PQ[g0]*(QC_1*delta[b1][d0] + QD_0*delta[b1][c1])) + PQ[b1]*(PQ[c1]*(QC_x*delta[a1][d0] + QD_0*delta[a1][g0]) + PQ[d0]*(QC_1*delta[a1][g0] + QC_x*delta[a1][c1]) + PQ[g0]*(QC_1*delta[a1][d0] + QD_0*delta[a1][c1]))) + PB_1*(PQ[a1]*(PQ[c1]*(QC_x*delta[b0][d0] + QD_0*delta[b0][g0]) + PQ[d0]*(QC_1*delta[b0][g0] + QC_x*delta[b0][c1]) + PQ[g0]*(QC_1*delta[b0][d0] + QD_0*delta[b0][c1])) + PQ[b0]*(PQ[c1]*(QC_x*delta[a1][d0] + QD_0*delta[a1][g0]) + PQ[d0]*(QC_1*delta[a1][g0] + QC_x*delta[a1][c1]) + PQ[g0]*(QC_1*delta[a1][d0] + QD_0*delta[a1][c1])))) + PA_1*(PB_0*(PQ[a0]*(PQ[c1]*(QC_x*delta[b1][d0] + QD_0*delta[b1][g0]) + PQ[d0]*(QC_1*delta[b1][g0] + QC_x*delta[b1][c1]) + PQ[g0]*(QC_1*delta[b1][d0] + QD_0*delta[b1][c1])) + PQ[b1]*(PQ[c1]*(QC_x*delta[a0][d0] + QD_0*delta[a0][g0]) + PQ[d0]*(QC_1*delta[a0][g0] + QC_x*delta[a0][c1]) + PQ[g0]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1]))) + PB_1*(PQ[a0]*(PQ[c1]*(QC_x*delta[b0][d0] + QD_0*delta[b0][g0]) + PQ[d0]*(QC_1*delta[b0][g0] + QC_x*delta[b0][c1]) + PQ[g0]*(QC_1*delta[b0][d0] + QD_0*delta[b0][c1])) + PQ[b0]*(PQ[c1]*(QC_x*delta[a0][d0] + QD_0*delta[a0][g0]) + PQ[d0]*(QC_1*delta[a0][g0] + QC_x*delta[a0][c1]) + PQ[g0]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])))) + PB_0*PB_1*(PQ[a0]*(PQ[c1]*(QC_x*delta[a1][d0] + QD_0*delta[a1][g0]) + PQ[d0]*(QC_1*delta[a1][g0] + QC_x*delta[a1][c1]) + PQ[g0]*(QC_1*delta[a1][d0] + QD_0*delta[a1][c1])) + PQ[a1]*(PQ[c1]*(QC_x*delta[a0][d0] + QD_0*delta[a0][g0]) + PQ[d0]*(QC_1*delta[a0][g0] + QC_x*delta[a0][c1]) + PQ[g0]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])))) + QC_x*QD_0*(PA_0*(PA_1*(PQ[b0]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0]) + PQ[b1]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0])) + PB_0*(PQ[a1]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0]) + PQ[b1]*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0])) + PB_1*(PQ[a1]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0]) + PQ[b0]*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0]))) + PA_1*(PB_0*(PQ[a0]*(PQ[c0]*delta[b1][c1] + PQ[c1]*delta[b1][c0]) + PQ[b1]*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0])) + PB_1*(PQ[a0]*(PQ[c0]*delta[b0][c1] + PQ[c1]*delta[b0][c0]) + PQ[b0]*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0]))) + PB_0*PB_1*(PQ[a0]*(PQ[c0]*delta[a1][c1] + PQ[c1]*delta[a1][c0]) + PQ[a1]*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0]))))

                            +(QC_0*(PQ[c1]*QD_0*QD_y*(PQ[d1]*QC_x + PQ[g0]*QD_1) + QC_x*(PQ[c1]*QD_1*(PQ[d0]*QD_y + PQ[g1]*QD_0) + QC_1*(PQ[d0]*(PQ[d1]*QD_y + PQ[g1]*QD_1) + PQ[d1]*PQ[g1]*QD_0))) + QC_1*QD_y*(PQ[c0]*QC_x + PQ[g0]*QC_0)*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + QD_0*QD_1*(PQ[c0]*QC_x*(PQ[c1]*QD_y + PQ[g1]*QC_1) + PQ[g0]*QC_1*(PQ[c0]*QD_y + PQ[g1]*QC_0)))*(PA_0*(-PA_1*delta[b0][b1] - PB_0*delta[a1][b1] - PB_1*delta[a1][b0] + PQ[a1]*delta[b0][b1] + PQ[b0]*delta[a1][b1] + PQ[b1]*delta[a1][b0]) + PA_1*(PQ[a0]*delta[b0][b1] + delta[a0][b0]*(-PB_1 + PQ[b1]) + delta[a0][b1]*(-PB_0 + PQ[b0])) + PB_0*(PQ[a0]*delta[a1][b1] + PQ[a1]*delta[a0][b1] + delta[a0][a1]*(-PB_1 + PQ[b1])) + PB_1*(PQ[a0]*delta[a1][b0] + PQ[a1]*delta[a0][b0] + PQ[b0]*delta[a0][a1]))

                        )


                    );

            double hess_kl_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
