1]*(delta[a0][c1]*delta[d1][g0] + delta[a0][d1]*delta[c1][g0] + delta[a0][g0]*delta[c1][d1])) + PQ[d1]*(PQ[g0]*(delta[a0][c1]*delta[d0][g1] + delta[a0][d0]*delta[c1][g1] + delta[a0][g1]*delta[c1][d0]) + PQ[g1]*(delta[a0][c1]*delta[d0][g0] + delta[a0][d0]*delta[c1][g0] + delta[a0][g0]*delta[c1][d0]))) + PQ[c1]*(PQ[d0]*(PQ[g0]*(delta[a0][c0]*delta[d1][g1] + delta[a0][d1]*delta[c0][g1] + delta[a0][g1]*delta[c0][d1]) + PQ[g1]*(delta[a0][c0]*delta[d1][g0] + delta[a0][d1]*delta[c0][g0] + delta[a0][g0]*delta[c0][d1])) + PQ[d1]*(PQ[g0]*(delta[a0][c0]*delta[d0][g1] + delta[a0][d0]*delta[c0][g1] + delta[a0][g1]*delta[c0][d0]) + PQ[g1]*(delta[a0][c0]*delta[d0][g0] + delta[a0][d0]*delta[c0][g0] + delta[a0][g0]*delta[c0][d0])))) + PQ[d0]*PQ[d1]*(PA_0*(PQ[c0]*(delta[a1][c1]*delta[g0][g1] + delta[a1][g0]*delta[c1][g1] + delta[a1][g1]*delta[c1][g0]) + PQ[c1]*(delta[a1][c0]*delta[g0][g1] + delta[a1][g0]*delta[c0][g1] + delta[a1][g1]*delta[c0][g0]) + PQ[g0]*(delta[a1][c0]*delta[c1][g1] + delta[a1][c1]*delta[c0][g1] + delta[a1][g1]*delta[c0][c1]) + PQ[g1]*(delta[a1][c0]*delta[c1][g0] + delta[a1][c1]*delta[c0][g0] + delta[a1][g0]*delta[c0][c1])) + PA_1*(PQ[c0]*(delta[a0][c1]*delta[g0][g1] + delta[a0][g0]*delta[c1][g1] + delta[a0][g1]*delta[c1][g0]) + PQ[c1]*(delta[a0][c0]*delta[g0][g1] + delta[a0][g0]*delta[c0][g1] + delta[a0][g1]*delta[c0][g0]) + PQ[g0]*(delta[a0][c0]*delta[c1][g1] + delta[a0][c1]*delta[c0][g1] + delta[a0][g1]*delta[c0][c1]) + PQ[g1]*(delta[a0][c0]*delta[c1][g0] + delta[a0][c1]*delta[c0][g0] + delta[a0][g0]*delta[c0][c1]))) + PQ[g0]*PQ[g1]*(PA_0*(PQ[c0]*(delta[a1][c1]*delta[d0][d1] + delta[a1][d0]*delta[c1][d1] + delta[a1][d1]*delta[c1][d0]) + PQ[c1]*(delta[a1][c0]*delta[d0][d1] + delta[a1][d0]*delta[c0][d1] + delta[a1][d1]*delta[c0][d0]) + PQ[d0]*(delta[a1][c0]*delta[c1][d1] + delta[a1][c1]*delta[c0][d1] + delta[a1][d1]*delta[c0][c1]) + PQ[d1]*(delta[a1][c0]*delta[c1][d0] + delta[a1][c1]*delta[c0][d0] + delta[a1][d0]*delta[c0][c1])) + PA_1*(PQ[c0]*(delta[a0][c1]*delta[d0][d1] + delta[a0][d0]*delta[c1][d1] + delta[a0][d1]*delta[c1][d0]) + PQ[c1]*(delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0]) + PQ[d0]*(delta[a0][c0]*delta[c1][d1] + delta[a0][c1]*delta[c0][d1] + delta[a0][d1]*delta[c0][c1]) + PQ[d1]*(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1]))))

