]*delta[b0][d1]) + delta[a0][d1]*(delta[a1][b0]*delta[d0][g1] + delta[a1][d0]*delta[b0][g1] + delta[a1][g1]*delta[b0][d0]) + delta[a0][g1]*(delta[a1][b0]*delta[d0][d1] + delta[a1][d0]*delta[b0][d1] + delta[a1][d1]*delta[b0][d0])) + PQ[d0]*(delta[a0][a1]*(delta[b0][b1]*delta[d1][g1] + delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + delta[a0][b0]*(delta[a1][b1]*delta[d1][g1] + delta[a1][d1]*delta[b1][g1] + delta[a1][g1]*delta[b1][d1]) + delta[a0][b1]*(delta[a1][b0]*delta[d1][g1] + delta[a1][d1]*delta[b0][g1] + delta[a1][g1]*delta[b0][d1]) + delta[a0][d1]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + delta[a0][g1]*(delta[a1][b0]*delta[b1][d1] + delta[a1][b1]*delta[b0][d1] + delta[a1][d1]*delta[b0][b1])) + PQ[d1]*(delta[a0][a1]*(delta[b0][b1]*delta[d0][g1] + delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0]) + delta[a0][b0]*(delta[a1][b1]*delta[d0][g1] + delta[a1][d0]*delta[b1][g1] + delta[a1][g1]*delta[b1][d0]) + delta[a0][b1]*(delta[a1][b0]*delta[d0][g1] + delta[a1][d0]*delta[b0][g1] + delta[a1][g1]*delta[b0][d0]) + delta[a0][d0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + delta[a0][g1]*(delta[a1][b0]*delta[b1][d0] + delta[a1][b1]*delta[b0][d0] + delta[a1][d0]*delta[b0][b1])) + PQ[g1]*(delta[a0][a1]*(delta[b0][b1]*delta[d0][d1] + delta[b0][d0]*delta[b1][d1] + delta[b0][d1]*delta[b1][d0]) + delta[a0][b0]*(delta[a1][b1]*delta[d0][d1] + delta[a1][d0]*delta[b1][d1] + delta[a1][d1]*delta[b1][d0]) + delta[a0][b1]*(delta[a1][b0]*delta[d0][d1] + delta[a1][d0]*delta[b0][d1] + delta[a1][d1]*delta[b0][d0]) + delta[a0][d0]*(delta[a1][b0]*delta[b1][d1] + delta[a1][b1]*delta[b0][d1] + delta[a1][d1]*delta[b0][b1]) + delta[a0][d1]*(delta[a1][b0]*delta[b1][d0] + delta[a1][b1]*delta[b0][d0] + delta[a1][d0]*delta[b0][b1])))

