                            +PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]*(PQ[a0]*PQ[b1]*(PA_1*PQ[b0] + PB_0*PQ[a1]) + PQ[a1]*PQ[b0]*(PA_0*PQ[b1] + PB_1*PQ[a0]))

                        )

                        + F10_t[9] * 4.0 * S1 * S1 * S1 * S1 * S1 * S2 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_k * a_l * (

                            -PQ[a0]*PQ[a1]*PQ[b0]*PQ[b1]*(PQ[c0]*PQ[c1]*(PQ[d0]*PQ[d1]*(PQ[g0]*QD_y + PQ[g1]*QC_x) + PQ[g0]*PQ[g1]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)) + PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]*(PQ[c0]*QC_1 + PQ[c1]*QC_0))

                        )

                        + F10_t[10] * 4.0 * S1 * S1 * S1 * S1 * S1 * S1 * S2 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_k * a_l * (

                            +PQ[a0]*PQ[a1]*PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]

                        )


                    );

            double hess_kl_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + k] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + l_prim],
                hess_kl_xy * ik_factor_D * 2.0 * frac_exact_exchange);
        }
    }

    __syncthreads();
}

}  // namespace gpu
